		\caption{Illustration of the induction step in~\cref{lem:cart-prod-power}. The Hamiltonian cycle~\(C_n\) of \(G^{\operatorname{\square} n}\) constructed from the Hamiltonian cycle~\(C_{n-1}\) of~\(G^{\operatorname{\square} n-1}\), here depicted for \(|C_{n-1}|=5\).}
		\label{fig:ham-cyc-GxH_ind}
	\end{figure}
	We start with the base case, i.e., $n=2$.
	For simplicity, we call the edges in~\(E_1\) and~\(E_2\) \textit{vertical} and \textit{horizontal} edges, respectively. Let~\((g_1, \dots, g_k)\) be a Hamiltonian cycle of~\(G\).
	From this cycle, we can construct the two Hamiltonian cycles~\(C_2\) and~\(\hat{C}_2\) of~\(G^{\operatorname{\square} 2}\) depicted in~\cref{fig:ham-cyc-GxH}. (Note that the constructions slightly change depending on the parity of \(|G|\), but the following arguments hold for both.)
	For the sake of contradiction, assume there is an automorphism~\({\varphi \in \operatorname{Aut}(G \operatorname{\square} G)}\) mapping~\(C_2\) to~\(\hat{C}_2\). Since every vertical edge in~\(\hat{C}_2\) is preceded and followed by horizontal edges (here we use $k\geq 4$), but all horizontal edges in~\(C_2\) are either preceded or followed by another horizontal edge,~\(\varphi\) cannot swap the sets~\(E_1\) and~\(E_2\), so it preserves each. But this leads to a contradiction because there are~\(k-1\) consecutive vertical edges in~\(C_2\), but not in~\(\hat{C}_2\).
	Also, note that both cycles contain at least $2(k-1)\geq 4$ edges from $E_1$ and from $E_2$ so that this completes the base case. 

	For the induction step, let~\(n \geq 3\).
	Let~\(u,v\) and~\(w\) be three consecutive vertices of~\(C_{n-1}\). Let~\(C_n\) be the cycle obtained from~\(C_{n-1}\) using~\(u,v\), and~\(w\) as depicted in~\cref{fig:ham-cyc-GxH_ind}. 
	Note here that the vertical edges in \cref{fig:ham-cyc-GxH_ind} are precisely the edges in $E_n$.
	Analogously, construct~\(\hat{C}_n\) from~\(\hat{C}_{n-1}\) and three consecutive vertices~\(\hat{u},\hat{v}\) and~\(\hat{w}\) in~\(\hat{C}_{n-1}\). 
	Note that 
	\begin{equation}\label{eq:IntersectionEn}
		|E(C_n) \cap E_n| = 2(k-1)\geq 4.
	\end{equation}
	Further, since $C_n$ contains $k$ copies of the cycle $C_{n-1}$ with one or two edges removed and, by the induction hypothesis, $C_{n-1}$ uses at least 4 edges from $E_i$, we~have
	\begin{equation}\label{eq:IntersectionEi}
		|E(C_n) \cap E_i| \geq 2k \geq 4
	\end{equation}
	for all~\(i \in \{1, \dots, n-1\}\). 
	We obtain analogs of the equations \eqref{eq:IntersectionEn} and \eqref{eq:IntersectionEi} for the cycle~$\hat{C}_n$.
	It remains to prove that the cycles cannot be mapped to each other.
	Assume there is an automorphism~\({\varphi_n \in \operatorname{Aut}(G^{\operatorname{\square} n})}\) mapping~\(C_n\) to~\(\hat{C}_n\).  
	Using \eqref{eq:IntersectionEn} and \eqref{eq:IntersectionEi}, we obtain that~	$|E(C_n) \cap E_n|=2(k-1)<2k\leq |E(\hat{C}_n) \cap E_i|$ for all $i\neq n$, so that~\(\varphi\) has to preserve the set~\(E_n\).  
	Thus,~\(\varphi_n\) is of the form~\((\varphi_{n-1}, \alpha)\) for some~\(\varphi_{n-1} \in \operatorname{Aut}(G^{\operatorname{\square} n-1})\) and~\(\alpha \in \operatorname{Aut}(G)\).
	Note that both cycles \(C_n\) and \(\hat{C}_n\) contain precisely one path of edges in $E_n$ of length $k-1$, so that $\varphi$ maps one to the other, i.e., the path \(((v,g_1), \dots, (v,g_k))\) in \(C_n\) is mapped to the path~\(((\hat{v},g_1), \dots, (\hat{v},g_k))\) in~\(\hat{C}_n\). 
	Hence,~\(\alpha\) either maps~\(g_1\) to~\(g_1\) or, in case~\(\alpha\) reverses the order of the path, to~\(g_k\). In both cases, \(\varphi_{n-1}\) maps~\(C_{n-1}\) to~\(\hat{C}_{n-1}\), which contradicts the induction hypothesis.
	Therefore, \(C_n\) cannot be mapped to \(\hat{C}_n\) by an automorphism. This completes
	the proof in case $k\geq 4$.

	Next, assume~\(k=3\). Since~\(G\) is Hamiltonian, this implies~\(G=K_3\). In the following, we refine the argument for \(|G| \geq 4\).
	First, consider the Hamiltonian cycles~\(C_2\) and~\(\hat{C}_2\) of~\(K_3^{\operatorname{\square} 2}\) depicted in~\cref{fig:K3-powers}. They cannot be mapped to each other by automorphisms of~\(K_3^{\operatorname{\square} 2}\), since~\(C_2\) has three horizontal edges, while~\(\hat{C}_2\) has at least four edges in each direction. This shows that~\(K_3^{\operatorname{\square} 2} \not \in \mathcal{H}\).

	Now, let~\(n \geq 3\). Consider the Hamiltonian cycles~\(C_n\) and~\(\hat{C}_n\) of~\(K_3^{\operatorname{\square} n}\) obtained from~\(C_{n-1}\) and~\(\hat{C}_{n-1}\) as before. Then,~\(C_n\) and~\(\hat{C}_n\) again have precisely four edges in~\(E_n\). Further, they have more than four edges in all~\(E_i\) for~\(i < n\):
	From the three copies of \(C_{n-1}\) (resp. \(\hat{C}_{n-1}\)) in the construction of \(C_n\) (resp. \(\hat{C}_{n}\)), we in total remove each of the edges \(\{v,w\}\) and \(\{u,v\}\) twice. Thus, for \(\hat{C}_{n-1}\), we have at least \(3 \cdot 4 - 4 = 8\) edges in each \(E_i\). For \(C_n\), note that there are no two consecutive horizontal edges in \(C_2\) and thus, \(C_3\) contains at least \(3 \cdot 3 - 2 = 7\) edges in each direction. Hence, \(C_n\) contains at least 7 edges in each \(E_i\). With this, the proof can be carried out as in the case $|G|\geq 4$.

\label{lem:cartesian-K2_odd_noncycle}
	Let $G$ be Hamiltonian with $|G|=:k$ odd and $G\neq C_k$. 
	Then $G \operatorname{\square} K_2 \notin \mathcal{H}$.

\label{lemma:divisibilitylemma}                    
	Let $G \in \mathcal{H}$ and assume that $G = \operatorname{Cay}(\Gamma, S)$ for an abelian group $\Gamma$ and a generating set $S$.
	\begin{enumerate}
		\item Suppose that $|\Gamma|$ is odd. If $S$ contains an element of order $pm$ for a prime $p$ and $m > 1$, then~$p$ divides $\kappa(G)$.
		\item If $|\Gamma|$ is even, then $\kappa(G)$ is even.
	\end{enumerate}

\label{lemma:small-groups}
	Let $G$ be the Cayley graph of an abelian group \(\Gamma\).
	\begin{itemize}
		\item Assume that $n:=|\Gamma|\leq 16$. Then $G \in \mathcal{H}$ if and only if one of the following holds
		\begin{itemize}
			\item $G \in \{K_n, C_n, C_4 \operatorname{\square} K_2\}$,
			\item $G=K_{k,k}$ where $k=n/2$,
			\item $G=C_k \operatorname{\square} K_2$ where $k=n/2$ is odd.
		\end{itemize}
		\item Assume that \(\Gamma \in \{\mathbb{Z}_3 \times \mathbb{Z}_3 \times \mathbb{Z}_3, \mathbb{Z}_9 \times \mathbb{Z}_3\}\). Then \(G \in \mathcal{H}\) if and only if \(G = K_{27}\).
	\end{itemize}

\label{thm:cyclic_generator}
	Let~\(\Gamma \cong \mathbb{Z}_n\) and~\(S\) be a generating set of~\(\Gamma\) containing an element of order~\(n\). Let~\(G = \operatorname{Cay}(\Gamma,S)\). Then, the following are equivalent:
	\begin{enumerate}
		\item $ G \in \mathcal{H}$, \label{item:cyclic_gen_graph_in_H}
		\item every Hamiltonian cycle~$C$ in~$G$ has Hamilton compression~$\kappa(C)=n$,  \label{item:cyclic_gen_rotation_one}
		\item we have $G \in \{K_n, C_n\}$ or $n=2m$ is even and $G=K_{m,m}$.\label{item:cyclic_gen_list_of_graphs_in_H}
	\end{enumerate}

\label{def:layer-structure}
	Let $G$ be a graph and $l \in \mathbb{N}_{\geq 1}$.
	If there is a decomposition $V(G) = V_1 \operatorname{\dot{\cup}} \dots \operatorname{\dot{\cup}} V_l$ such that
	\begin{enumerate}
		\item for $i \in \{1, \dots, l-1\}$, $G$ contains a perfect matching between $V_i$ and $V_{i+1}$ that defines an isomorphism between $G[V_i]$ and $G[V_{i+1}]$, and
		\item the graph $K:= G[V_1] \cong \dots \cong G[V_l]$ is Hamiltonian,
	\end{enumerate}
	we say that~$G$ has~\emph{$K$-$l$-layer structure}.
	In this case, we call $G[V_1], \dots ,G[V_l]$ the \emph{layers} of~$G$.

\label{lem:zigzag_mu}
	Let $G$ be a graph with $K$-$l$-layer structure, where $l\geq 5$ is odd, let $k:=|K|$, and let $C$ be the $C_K$-$\ensuremath{\boldsymbol{a}}$-zigzag cycle for some choice of $C_K$ and $\ensuremath{\boldsymbol{a}}$. Then we have
	\begin{equation*}
		\mu(C)=2k-1+2\sum_{i=1}^{(l-3)/2} (a_i+1).
	\end{equation*}

	In particular, we obtain that $\mu(C)$ is odd. 
	Even further, for any odd number $\mu^*\in \mathbb{N}$ with~$2k-1+(l-3)\leq \mu^* \leq 2k-1+(l-3)(k-1)$, there is a choice for $\ensuremath{\boldsymbol{a}}$ such that the~$C_K$-$\ensuremath{\boldsymbol{a}}$-zigzag cycle $C$ fulfills~$\mu(C)=\mu^*$.

\label{thm:layerstructure}
	Let $G \in \mathcal{H}$ be a graph of odd order that has $K$-$l$-layer structure and let~$k:=|K|$.
	Assume that one of the following conditions holds
	\begin{enumerate}
		\item $k,l\geq 7$ and $\kappa(G)\geq 5$
		\item $k,l \geq 5$ and, for every prime $p$ with $p|n:=|G|$, we have $p|\kappa(G)$.
	\end{enumerate}
	Then~$K$ is isomorphic to $C_k$ or $K_k$.

\label{lemma:cayleycycle}
Let $\Gamma$ be an abelian group of odd order with generating set $S$. 
Suppose that the Cayley graph $G = \operatorname{Cay}(\Gamma,S)$ is Hamiltonian-transitive and  $\kappa(G) > 1$. Assume that $G$ has a group-induced $K$-$l$-layer structure with $k\coloneqq|K|\geq 5$ and $l\geq5$. Then we have $K \not \cong C_k$.
